    [1214104245] = {
        ["english"] = { [1] = "Stable Master" },
        ["text"] = "Доглядач стайні",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
