    [1233882911] = {
        ["english"] = { [1] = "I would like to go to the battleground." },
        ["text"] = "Я хочу піти на поле бою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
