    [3986850573] = {
        ["english"] = {},
        ["text"] = "Вітаю, дворфе.",
        ["npcs"] = { [1] = 11146 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
