    },
    [2340710306] = {
        ["english"] = { [1] = "Have you come seeking training in the ways of armed combat?" },
        ["text"] = "Прийшли опановувати бойове мистецтво зі зброєю?",
        ["npcs"] = { [1] = 11867 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
