    [1132330448] = {
        ["english"] = {},
        ["text"] = "Ласкаво просимо, {стать:воїне:воїтелько}, до Імлистої Сосни. Якщо ти втомився з дороги, заходь, відпочинь і зігрійся. А якщо маєш трохи часу, може, допоможеш мені з кількома справами.",
