        ["source_status"] = "missing",
    },
    [4189965412] = {
        ["english"] = { [1] = "Cooking is a life long pursuit and I see we share the same passion!" },
        ["text"] = "Куховарство — справа всього життя, і я бачу, що ми поділяємо це захоплення!",
