    [751186203] = {
        ["english"] = {},
        ["text"] = "Вітаю, {клас:к}.\013\010\013\010Я можу показати вам, як оповити себе чарами, щоб змінити вигляд свого спорядження, якщо забажаєте. Бажаєте скористатися моїми послугами?",
