    [3433948923] = {
        ["english"] = {},
        ["text"] = "Шукаєш гінця? Щойно полетів геть, наче маленька пташка.\010\010Не можу винуватити бідолаху. З цими вендиго кепські справи.",
        ["npcs"] = { [1] = 271546 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
