    [2806813727] = {
        ["english"] = { [1] = "Greetings, $c! Fine day for hunting, wouldn't you say? I've been having more than a little luck with boars, myself. Perhaps you'd like a shot?" },
        ["text"] = "Вітаю, магу! Чудовий день для полювання, чи не так? Мені й самому неабияк щастить на вепрів. Може, й ти хочеш спробувати?",
        ["npcs"] = { [1] = 714 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "gscsfedyfrhgwtyusyiebnhgmetnlelkwhbsmfpsydlest" },
        },
        ["source_status"] = "unique_source_candidate",
    },
    [449351295] = {
        ["english"] = {},
        ["text"] = "Вітаю, юначе. Я Ґрелін Білобородий. Я тут, щоб дослідити загрозу, яку становить дедалі більша кількість тролів у Долині Морозного Хребта. Що я з'ясував? Дещо тривожне...",
        ["npcs"] = { [1] = 786 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "gsldimgnwdimhetoeetettpdbyteggnsoftsincevywthefdisbttg" },
        },
        ["source_status"] = "ambiguous",
    },
    [3599619743] = {
        ["english"] = {},
        ["text"] = "Вітаю, {стать:воїне:воїтелько}. Я — Верховний штукар Меккакруть, вигнанець із Гномреґану.",
        ["npcs"] = { [1] = 7937 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "hotewramhhtrmeofteesofgn" },
        },
        ["source_status"] = "missing",
    },
    [1702116538] = {
        ["english"] = {},
        ["text"] = "Я — мехмайстер Надспалах, головний архітектор сучасних засад гномської інженерії в усьому світі! Моє завдання — стежити, щоб сила винахідництва й надалі сяяла в наших дугових гайковертах яскравіше, ніж будь-де інде!\010\010До речі, якщо тобі відоме добре креслення для усунення радіації, ми саме зараз шукаємо щось подібне...",
        ["npcs"] = { [1] = 7944 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "amtrokadamtecfatfrmnghegpsintewdtyitismyjbtoeettteprofincstosebtfmoratsstnaeeeaoifyuhntokwgdscfrrnenwejtsohntobeintemtfroertatnw" },
        },
        ["source_status"] = "missing",
    },
    [152460222] = {
        ["english"] = { [1] = "Erm... I really don't know you that well, sorry.  I mean, as an authorized Mechano-strider dealer, I really only can sell my mounts to those people who are considered exalted amongst the gnomes.  If you ever are recognized as exalted to Gnomeregan, I'd be happy to show you what I have to offer." },
        ["text"] = "Ем... Вибач, але я тебе зовсім не знаю. Як уповноважений продавець механобігів, я можу продавати своїх скакунів лише тим, кого гноми вважають превознесеними. Якщо ти заслужиш превознесення в Гномреґані, я радо покажу тобі свій товар.",
        ["npcs"] = { [1] = 7955 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "emrydtkwyuttwlsymnasanadmrdrryoycnslmymstotepewoaecdedattegsifyueraerdasedtognidbehytoswyuwthetoor" },
        },
        ["source_status"] = "unique_source_candidate",
    },
    [4031819490] = {
        ["english"] = { [1] = "I sell the finest cloth and leather garb this side of the valley!" },
        ["text"] = "Я продаю найкращий одяг із тканини та шкіри по цей бік долини!",
        ["npcs"] = { [1] = 836 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "slteftchadlrgbtsseoftevy" },
        },
        ["source_status"] = "unique_source_candidate",
    },
    [1224797151] = {
        ["english"] = {},
        ["text"] = "Служи Світлу гідно, {стать:воїне:воїтелько}.",
        ["npcs"] = { [1] = 837 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "seteltwlwr" },
        },
        ["source_status"] = "missing",
    },
    [916388844] = {
        ["english"] = { [1] = "Wanna buy a cockroach?" },
        ["text"] = "Хочеш купити таргана?",
        ["npcs"] = { [1] = 8403 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "hash", ["value"] = 916388844 },
        },
        ["source_status"] = "verified_comment",
    },
    [3636201544] = {
        ["english"] = { [1] = "Arathi Basin was once our home, and will be again with your aid!  Will you help us $c?" },
        ["text"] = "Низина Араті колись була нашим домом і з твоєю допомогою знову ним стане! Допоможеш нам, {клас:к}?",
        ["npcs"] = { [1] = 857 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "aibnwsoeorheadwlbeanwhyradwlyuhpuscs" },
        },
        ["source_status"] = "unique_source_candidate",
    },
    [2614069872] = {
        ["english"] = { [1] = "I... I'm not really sure how I got here...\010\010I seem to remember traveling... a raft..." },
        ["text"] = "Я... якщо чесно, я не зовсім розумію, як я сюди потрапив...\010\010Здається, я кудись плив... на плоті...",
        ["npcs"] = { [1] = 8737 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "hash", ["value"] = 2614069872 },
        },
        ["source_status"] = "verified_comment",
    },
    [4260626268] = {
        ["english"] = {},
        ["text"] = "Вітаю, {ім'я:к}. Ти {стать:прийшов:прийшла} дізнатися про історію Залізогарта?",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "gsdnheyucetolnoftehyofie" },
        },
        ["source_status"] = "missing",
    },
    [1298350057] = {
        ["english"] = { [1] = "I can tell just by the way you're standing that you're no warrior.\010\010Why don't you go do something safe, like read a book." },
        ["text"] = "Я бачу, що ти не {стать:воїн:воїтелька}, просто по тому як ти стоїш.\010\010Чому б тобі не зайнятися чимось безпечним, наприклад почитати книжку.",
        ["npcs"] = { [1] = 911 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "hash", ["value"] = 1298350057 },
        },
        ["source_status"] = "verified_comment",
    },
    [2546856024] = {
        ["english"] = {},
        ["text"] = "Вітаю.  Я навчаю гномів-магів, а ти — маг.",
        ["npcs"] = { [1] = 944 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
        ["priority"] = 1,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "gsimgecstradyecs" },
        },
        ["source_status"] = "missing",
    },
    [2977896244] = {
    ["english"] = { [1] = "The Wind Spirits have left us. \013\010\013\010Now, only mindless echoes now remain. Be wary, however. These winds are neither kind, nor gentle." },
    ["text"] = "Духи Вітру покинули нас. \013\010\013\010Тепер лишилися лише бездумні відлуння. Та будьте обережні. Ці вітри не добрі й не лагідні.",
    ["npcs"] = { [1] = 249363 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [3514185823] = {
    ["english"] = { [1] = "What do you need of me, child of Zephras?" },
    ["text"] = "Що тобі від мене потрібно, дитя Зефрасу?",
    ["npcs"] = { [1] = 251361 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [718238403] = {
    ["english"] = { [1] = "Hello, <class>." },
    ["text"] = "Вітаю, {клас:к}.",
    ["npcs"] = { [1] = 251362 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2567501641] = {
    ["english"] = { [1] = "Greetings to you, fellow High Order initiate." },
    ["text"] = "Вітаю тебе, побратиме-послушнику Високого Ордену.",
    ["npcs"] = { [1] = 251371 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [1915224855] = {
    ["english"] = { [1] = "Magic can accomplish almost anything, but stagnation and inaction have caused us to lose so much of ourselves in the thousands of years since we left Kalimdor. The High Order seeks to reclaim the Highborne heritage that we've left behind and become the masters of our own destiny once again.\013\010\013\010The Windshapers think we are simply reckless and arrogant. Hypocrisy at its finest, if you ask me. The Windshapers will entertain no ideas but their own when it comes to this crisis. Who, I wonder, is truly arrogant?" },
    ["text"] = "Магія здатна майже на все, та застій і бездіяльність змусили нас втратити надто багато від самих себе за тисячі років, що минули відтоді, як ми покинули Калімдор. Високий Орден прагне повернути спадщину Високородних, яку ми залишили позаду, і знову стати господарями власної долі.\013\010\013\010Вітротворці вважають нас просто безрозсудними й пихатими. Найвища міра лицемірства, як на мене. У цій кризі вітротворці не бажають чути жодних ідей, окрім власних. То хто ж, питається, насправді пихатий?",
    ["npcs"] = { [1] = 251371 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [292205191] = {
    ["english"] = { [1] = "May you tell me more about the state of Zephras Isle and the High Order?" },
    ["text"] = "Чи можеш розповісти мені більше про становище на острові Зефрас і Високий Орден?",
    ["npcs"] = { [1] = 251371 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [3309877597] = {
    ["english"] = { [1] = "What can you tell me about the status of the High Order?" },
    ["text"] = "Що ти можеш розповісти мені про становище Високого Ордену?",
    ["npcs"] = { [1] = 251371 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [3621490287] = {
    ["english"] = { [1] = "Zephras is in great danger. The elemental wind spirits that brought us here to Skywall so many thousands of years ago have abandoned us, leaving us vulnerable in this unstable realm. Our once-robust society spanned multiple island sanctuaries in our corner of Skywall, but now we are not even sure if any other shen'dorei remain outside of this small island.\013\010\013\010Things are dire, but the High Order is committed to rising to this challenge." },
    ["text"] = "Зефрас у великій небезпеці. Стихійні духи вітру, що привели нас сюди, до Небесної Стіни, багато тисяч років тому, покинули нас, лишивши беззахисними в цьому нестабільному царстві. Колись наше міцне суспільство охоплювало численні острівні святилища в нашій частині Небесної Стіни, та нині ми навіть не певні, чи лишилися ще якісь шен'дорай за межами цього малого острова.\013\010\013\010Становище тяжке, але Високий Орден сповнений рішучості прийняти цей виклик.",
    ["npcs"] = { [1] = 251371 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [412768463] = {
    ["english"] = { [1] = "I'd like training!" },
    ["text"] = "Я хочу навчатися!",
    ["npcs"] = { [1] = 251373 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
    ["alternatives"] = { [1] = {
    ["english"] = { [1] = "I'd like training!" },
    ["text"] = "Я хочу навчатися!",
    ["npcs"] = { [1] = 251991 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
 [2] = {
    ["english"] = { [1] = "I'd like training!" },
    ["text"] = "Я хочу навчатися!",
    ["npcs"] = { [1] = 254081 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    },
},
    [3564436627] = {
    ["english"] = { [1] = "If you have the aptitude for the druidic arts, I can train you." },
    ["text"] = "Якщо маєш хист до друїдського мистецтва, я можу тебе навчити.",
    ["npcs"] = { [1] = 251373 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
    ["alternatives"] = { [1] = {
    ["english"] = { [1] = "If you have the aptitude for the druidic arts, I can train you." },
    ["text"] = "Якщо маєш хист до друїдського мистецтва, я можу тебе навчити.",
    ["npcs"] = { [1] = 254081 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
} },
},
    [1162274109] = {
    ["english"] = { [1] = "The spirits of the wind may have left us, but the power of the elements is not entirely out of reach for those with the patience to seek them out.\013\010\013\010If you are initiated in the ways of the shaman, I can help you grasp them." },
    ["text"] = "Духи вітру, можливо, й покинули нас, але сила стихій не зовсім недосяжна для тих, хто має терпіння її шукати.\013\010\013\010Якщо тебе посвячено в шаманські звичаї, я допоможу тобі опанувати їх.",
    ["npcs"] = { [1] = 251374 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [357863533] = {
    ["english"] = { [1] = "The hunters and rangers of Zephras have never been more needed. The winds grow ever harsher, and the magic that sustains our island is fading. The wilds have never been more wild and people like me are needed to keep our people safe.\013\010\013\010If you have the proper aptitude as a hunter, I can give you the tools to survive the wilds." },
    ["text"] = "Мисливці та слідопити Зефрасу ще ніколи не були нам так потрібні. Вітри стають дедалі лютішими, а магія, що підтримує наш острів, згасає. Дика природа ще ніколи не була такою дикою, і такі, як я, потрібні, щоб берегти наш народ.\013\010\013\010Якщо маєш належний хист мисливця, я дам тобі засоби, потрібні для виживання в дикій природі.",
    ["npcs"] = { [1] = 251376 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2199751182] = {
    ["english"] = { [1] = "I can tell by your aura that you are of Highborne lineage, yes? Those that call themselves members of the High Order find very little common ground with the members of my order, the Windshapers. Outside the relative harmony of Thendal Grove, you may find that these divisions run very deep, deep enough to drive division and even violence.\013\010\013\010Be mindful of this as you move throughout Zephras Isle. I'll offer you this one warning... do not cross the Windshapers." },
    ["text"] = "За твоєю аурою бачу, що в тобі тече кров Високородних, так? Ті, хто називають себе членами Високого Ордену, мають дуже мало спільного з членами мого ордену — вітротворцями. За межами відносної злагоди гаю Тендала ти побачиш, що цей розкол дуже глибокий — настільки, що породжує ворожнечу й навіть насильство.\013\010\013\010Пам'ятай про це, подорожуючи островом Зефрас. Дам тобі лише одне застереження... не переходь дорогу вітротворцям.",
    ["npcs"] = { [1] = 251487 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [234273307] = {
    ["english"] = { [1] = "May you tell me more about the state of Zephras Isle and the Windshapers?" },
    ["text"] = "Чи можеш розповісти мені більше про становище на острові Зефрас і вітротворців?",
    ["npcs"] = { [1] = 251487 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [3756736407] = {
    ["english"] = { [1] = "<Constable Aonda wears an intense look on her face, clearly deep in thought.>" },
    ["text"] = "<На обличчі констебля Аонди застиг напружений вираз — видно, що вона глибоко замислилася.>",
    ["npcs"] = { [1] = 251523 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2630400274] = {
    ["english"] = { [1] = "Constable, can you tell me what is happening here in the Shen'dar Highlands?" },
    ["text"] = "Констеблю, можеш розповісти, що тут відбувається, у Шен'дарському нагір'ї?",
    ["npcs"] = { [1] = 251523 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [1043994998] = {
    ["english"] = { [1] = "Alas, I have prattled on long enough. Should you find yourself in the port of Valanaar, seek out Elaadrin Evengale. Elaadrin was once my student, but now he serves as the Chief Magister of the High Order. He is headstrong and capable, and it's now up to him and young Skyborne such as yourself to carry the hopes for our people forward." },
    ["text"] = "Та годі, я й так надто довго балакаю. Якщо опинишся в порту Валанаар, розшукай Елаадріна Вічновітра. Колись Елаадрін був моїм учнем, а тепер служить Верховним магістром Високого Ордену. Він упертий, але здібний, і тепер саме йому та молодим Небородним, таким як ти, належить нести вперед надії нашого народу.",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [4104113278] = {
    ["english"] = { [1] = "Can you tell me what is happening on Zephras Isle?" },
    ["text"] = "Можеш розповісти, що відбувається на острові Зефрас?",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [2926486503] = {
    ["english"] = { [1] = "Do we know why..?" },
    ["text"] = "Ми знаємо чому..?",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [666565627] = {
    ["english"] = { [1] = "Even the Windshapers would tell you that the spirits never spoke highly of any supreme being amongst them. They acknowledged the existence of a being named Al'Akir, but they avoided invoking his name, almost as if they feared him.\013\010\013\010Even if this Al'Akir is an all-powerful \"Windlord\" or ruler of the wind elementals, relying upon elementals is what got us into this mess. We must now see ourselves out of it." },
    ["text"] = "Навіть вітротворці скажуть тобі, що духи ніколи не говорили з пошаною про якусь найвищу істоту серед них. Вони визнавали існування істоти на ім'я Ал'Акір, але уникали навіть згадувати його ім'я, наче боялися його.\013\010\013\010Навіть якщо цей Ал'Акір — всемогутній «Володар Вітру» чи правитель вітряних елементалів, саме залежність від елементалів і завела нас у цю скруту. Тепер ми мусимо вибратися з неї самі.",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2179324815] = {
    ["english"] = { [1] = "Hello there, young <class>. I am Rathiril Sunlance and I am an elder Magister of the High Order here on Zephras Isle. It's always good to see bright-eyed young shen'dorei, ready to do their duty in service to their homeland.\013\010\013\010Don't let this dusty old mage hold you up however, no doubt you've got many adventures to see to. Feel free to stop by later if you'd like to speak more." },
    ["text"] = "Вітаю, юний {клас:к}. Я Ратіріл Сонцеспис, старший магістр Високого Ордену тут, на острові Зефрас. Завжди приємно бачити молодих шен'дорай з вогником в очах, готових виконувати свій обов'язок перед батьківщиною.\013\010\013\010Та не дозволяй цьому запиленому старому магу тебе затримувати — без сумніву, на тебе чекає чимало пригод. Заходь пізніше, якщо захочеш ще поговорити.",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [1474133979] = {
    ["english"] = { [1] = "How can you be so sure? If we've never dealt with the windlord directly, surely it's worth a try?" },
    ["text"] = "Звідки така впевненість? Якщо ми ніколи не мали справи з Володарем Вітру напряму, хіба не варто хоча б спробувати?",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [2168189917] = {
    ["english"] = { [1] = "How do we solve this?" },
    ["text"] = "Як нам це розв'язати?",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [1971779115] = {
    ["english"] = { [1] = "Many disagree on this point. The Windshapers would have you believe that joining hands and merely hoping for the spirits' return will be sufficient. Their order's power has waned however, and their path relies on putting us back on the cycle of dependence that got us to this point. The High Order on the other hand... we believe in a more direct approach." },
    ["text"] = "Багато хто з цим не погоджується. Вітротворці хочуть, щоб ти повірив: достатньо взятися за руки й просто сподіватися на повернення духів. Та сила їхнього ордену згасла, а їхній шлях знову заганяє нас у коло залежності, яке й привело нас сюди. Високий Орден, натомість... вірить у пряміший підхід.",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2301805668] = {
    ["english"] = { [1] = "<Remain Silent>" },
    ["text"] = "<Мовчати>",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [4002487487] = {
    ["english"] = { [1] = "The Cult? They are zealots and killers. They believe that we are being punished for some unspecific sin. The reality is that those that lead them are opportunists leftover from a dubious order of so-called \"Priests\" of Al'Akir, the Windlord. \013\010\013\010They now find themselves in a position to weaponize the fear of our people to consolidate their own power... and they have been quick to do so." },
    ["text"] = "Культ? Це фанатики й убивці. Вони вірять, що нас карають за якийсь незбагненний гріх. Насправді ж їхні ватажки — пристосуванці, що лишилися від сумнівного ордену так званих «Жерців» Ал'Акіра, Володаря Вітру. \013\010\013\010Тепер вони мають нагоду обернути страх нашого народу на зброю, щоб зміцнити власну владу... і не забарилися нею скористатися.",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [4022612132] = {
    ["english"] = { [1] = "Where to begin? Our home is failing. The wards have fallen and the three provinces have begun to drift apart. There was a time not long ago when the spires of Shen'dramar were visible from the western watchtower. No longer. Day by day the wind pylons that anchor our home to this plane weaken..." },
    ["text"] = "З чого почати? Наш дім гине. Обереги впали, і три провінції почали віддалятися одна від одної. Ще не так давно шпилі Шен'драмара було видно із західної сторожової вежі. Тепер — ні. День за днем вітряні пілони, що утримують наш дім на цьому плані, слабшають...",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [1892848984] = {
    ["english"] = { [1] = "I wish to ask you something else." },
    ["text"] = "Я хочу запитати дещо інше.",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [874437703] = {
    ["english"] = { [1] = "What about the Al'Aketh? Can they help?" },
    ["text"] = "А як щодо Ал'Акету? Вони можуть допомогти?",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [70818307] = {
    ["english"] = { [1] = "What of this \"Windlord\"? Is Al'Akir real, or a creation of the cult?" },
    ["text"] = "А що з цим «Володарем Вітру»? Ал'Акір справжній чи це вигадка культу?",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [537860307] = {
    ["english"] = { [1] = "Why is this happening? Put simply, the spirits of the wind just... vanished. \013\010\013\010The petty sprites and lesser elementals you've likely encountered out there are a pale imitation of the true spirits of wind. Non-sentient, aimless, and a far cry from the kindly spirits we lived in harmony alongside for thousands of years." },
    ["text"] = "Чому це відбувається? Якщо коротко, духи вітру просто... зникли. \013\010\013\010Дрібні духи та слабші елементалі, яких ти, ймовірно, зустрічав там, — лише бліда подоба справжніх духів вітру. Нерозумні, безцільні й зовсім не схожі на добрих духів, із якими ми жили в злагоді тисячі років.",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [3309808823] = {
    ["english"] = { [1] = "You must remember that while this realm has been our home for millennia, we will always be somewhat alien to this place. We are not in the terrestrial world that birthed our people. We are in the realm of Skywall, the elemental plane of air. \013\010\013\010We arrived here as the guests of spirits with whom we found kinship in ages past. Now that we Shen'dorei find ourselves bereft of their presence--and potentially--their protection, there's no telling how the other denizens of this plane may perceive us." },
    ["text"] = "Пам'ятай: хоч це царство й було нашим домом тисячоліттями, ми завжди лишатимемося тут певною мірою чужинцями. Ми не в земному світі, де народився наш народ. Ми в царстві Небесної Стіни — стихійному плані повітря. \013\010\013\010Ми прибули сюди як гості духів, із якими породичалися в давні віки. Тепер, коли ми, шен'дорай, позбавлені їхньої присутності — а можливо, й захисту, — важко сказати, як нас сприймуть інші мешканці цього плану.",
    ["npcs"] = { [1] = 251903 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [3590830344] = {
    ["english"] = { [1] = "If you need training as a cook, I have a few tips and tricks I could pass on! Ho ho! Throw on an apron and let's get started!" },
    ["text"] = "Якщо тобі потрібне навчання кухарської справи, я можу поділитися кількома хитрощами! Хо-хо! Одягай фартух — і до роботи!",
    ["npcs"] = { [1] = 251905 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [1255088542] = {
    ["english"] = { [1] = "Unless you are here on business pertaining to V.L.O., I'm afraid I won't have a lot of time for chatter. If you want to pitch in and help out around town, I'll certainly put you to work though.\013\010\013\010Oh, what does V.L.O. stand for? Village Live Operations, of course. Even frontier towns like these don't manage themselves. Between major incidents, unplanned wind power outages, and bug infestations, keeping this place moving forward is no joke." },
    ["text"] = "Якщо ти не у справах В.О.С., боюся, на балачки в мене небагато часу. Але якщо хочеш долучитися й допомогти містечку, роботу я тобі знайду.\013\010\013\010А, що означає В.О.С.? «Виробничі операції селища», звісно. Навіть такі прикордонні поселення не керують собою самі. Великі надзвичайні події, незаплановані перебої з вітровою енергією, навали комах — підтримувати тут усе в русі зовсім не жарти.",
    ["npcs"] = { [1] = 251906 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [535210813] = {
    ["english"] = { [1] = "I can teach you to swing a blacksmith's hammer, if you are willing to learn." },
    ["text"] = "Я можу навчити тебе вправлятися з ковальським молотом, якщо бажаєш учитися.",
    ["npcs"] = { [1] = 251913 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [406805991] = {
    ["english"] = { [1] = "The clothcraft of the Shen'dorei is a harmonious imitation of the flowing, carefree currents of the winds. While the spirits have left us, and I know not when I may see them dance once more... I find great comfort in my art, if only as a distraction.\013\010\013\010I can teach you to work the cloth as well, if you'd like to learn?" },
    ["text"] = "Ткацьке ремесло шен'дорай — гармонійне наслідування плинних, безтурботних течій вітру. Духи покинули нас, і я не знаю, коли знову побачу їхній танок... та моє ремесло дарує мені велику втіху, хай навіть лише відволікає думки.\013\010\013\010Я можу навчити й тебе працювати з тканиною, якщо хочеш?",
    ["npcs"] = { [1] = 251991 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [842068595] = {
    ["english"] = { [1] = "I can teach you to craft fine leather armor, if you have the aptitude." },
    ["text"] = "Я можу навчити тебе виготовляти добротний шкіряний обладунок, якщо маєш до цього хист.",
    ["npcs"] = { [1] = 251993 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2609974667] = {
    ["english"] = { [1] = "Be on your guard here in the highlands, citizen. There are many dangers between the beasts roaming the wild, murderous bandits, and the looming threat of the Al'Aketh." },
    ["text"] = "Будь насторожі тут, у нагір'ї, громадянине. Довкола чимало небезпек: звірі в дикій природі, кровожерливі бандити й нависла загроза Ал'Акету.",
    ["npcs"] = { [1] = 253474 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [398224003] = {
    ["english"] = { [1] = "Greetings, citizen." },
    ["text"] = "Вітаю, громадянине.",
    ["npcs"] = { [1] = 253474 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2598891253] = {
    ["english"] = { [1] = "The followers of the old Highborne ways have never been more hungry for knowledge and to reclaim what we've lost. If you would seek to wield the power of the arcane and have the aptitude, I can help you take your next steps." },
    ["text"] = "Послідовники давніх звичаїв Високородних ще ніколи так не прагнули знань і повернення втраченого. Якщо ти хочеш опанувати силу аркани й маєш до цього хист, я допоможу зробити наступні кроки.",
    ["npcs"] = { [1] = 254086 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [32352940] = {
    ["english"] = { [1] = "Slay your enemies and swoon your paramours with this one weird trick.\013\010\013\010If you follow the path of the rogue, I can teach you... for a cost, of course." },
    ["text"] = "Убивай ворогів і зводь із розуму коханих одним дивним трюком.\013\010\013\010Якщо йдеш шляхом розбійника, я можу тебе навчити... за певну плату, звісно.",
    ["npcs"] = { [1] = 254087 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [4289093006] = {
    ["english"] = { [1] = "The warrior who flinches is the warrior who dies. If you would look death in the face as a warrior, I will teach you how not to flinch." },
    ["text"] = "Воїн, який здригається, — мертвий воїн. Якщо ти готовий як воїн дивитися смерті просто у вічі, я навчу тебе не здригатися.",
    ["npcs"] = { [1] = 254088 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2870196171] = {
    ["english"] = { [1] = "Welcome to the Calmbreeze Inn, traveler. Would you like some refreshment?" },
    ["text"] = "Ласкаво просимо до заїзду «Тихий Бриз», мандрівнику. Бажаєш освіжитися?",
    ["npcs"] = { [1] = 254089 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [1214834136] = {
    ["english"] = { [1] = "Gales greetings, friend. Is there something I can help you with?" },
    ["text"] = "Вітряного привіту, друже. Чим можу допомогти?",
    ["npcs"] = { [1] = 257018 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [2393206562] = {
    ["english"] = { [1] = "I hope that your interruption is for a good cause, I was in the middle of some important work." },
    ["text"] = "Сподіваюся, ти відволікаєш мене з поважної причини. Я саме був посеред важливої роботи.",
    ["npcs"] = { [1] = 257019 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
    ["alternatives"] = { [1] = {
    ["english"] = { [1] = "I hope that your interruption is for a good cause, I was in the middle of some important work." },
    ["text"] = "Сподіваюся, ти відволікаєш мене з поважної причини. Я саме був посеред важливої роботи.",
    ["npcs"] = { [1] = 257024 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
} },
},
    [2320575580] = {
    ["english"] = { [1] = "Winds tidings. What can I help you with?" },
    ["text"] = "Добрих вітрів. Чим можу допомогти?",
    ["npcs"] = { [1] = 257019 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
    ["alternatives"] = { [1] = {
    ["english"] = { [1] = "Winds tidings. What can I help you with?" },
    ["text"] = "Добрих вітрів. Чим можу допомогти?",
    ["npcs"] = { [1] = 257020 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
} },
},
    [491025853] = {
    ["english"] = { [1] = "Welcome to my shop, it's good to see another Enchanter here in Shen'dar. Are you here for a lesson perhaps?" },
    ["text"] = "Ласкаво прошу до моєї крамниці. Приємно бачити ще одного зачаровувача тут, у Шен'дарі. Можливо, ти прийшов на урок?",
    ["npcs"] = { [1] = 257020 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [1794442875] = {
    ["english"] = { [1] = "Ah, hello. You look as though you have a question for me." },
    ["text"] = "А, вітаю. Схоже, у тебе є до мене запитання.",
    ["npcs"] = { [1] = 257024 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [1603678591] = {
    ["english"] = { [1] = "Halaan, please lend me your gift." },
    ["text"] = "Галаане, будь ласка, позич мені свій дар.",
    ["npcs"] = { [1] = 257554 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [2634272460] = {
    ["english"] = { [1] = "<The gaze of the ranger standing before you is fixed on the enormous anchor pylon in the distance.>" },
    ["text"] = "<Погляд слідопита перед тобою прикутий до велетенського якірного пілона вдалині.>",
    ["npcs"] = { [1] = 257554 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [864681595] = {
    ["english"] = { [1] = "It can get boring up here, you know. I can only annoy that stuffy wretch Halaan so much before even that gets old." },
    ["text"] = "Знаєш, тут нагорі буває нудно. Я можу дражнити того пихатого зануду Галаана лише до певної межі, а потім навіть це набридає.",
    ["npcs"] = { [1] = 263113 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [666762849] = {
    ["english"] = { [1] = "I would like to rewrite my legacy." },
    ["text"] = "Я хочу переписати свою спадщину.",
    ["npcs"] = { [1] = 2198 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    [342237054] = {
    ["english"] = { [1] = "Yes. I would like to unlearn my legacy talents." },
    ["text"] = "Так. Я хочу забути свої таланти спадщини.",
    ["npcs"] = { [1] = 2198 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
    ["alternatives"] = { [1] = {
    ["english"] = { [1] = "Yes. I would like to unlearn my legacy talents." },
    ["text"] = "Так. Я хочу забути свої спадкові таланти.",
    ["npcs"] = { [1] = 1901 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
} },
},
    [3136726784] = {
    ["english"] = { [1] = "I am told the farms of Westfall once supplied a bounty of crops for Stormwind. But now, the soil is barren and most of the farmers have fled.\013\010\013\010On behalf of Darnassus I would like to offer my aid in replenishing this land. Will you assist me?" },
    ["text"] = "Кажуть, колись ферми Західного Краю щедро постачали врожаї до Штормовію. Та нині земля тут безплідна, а більшість фермерів утекли.\013\010\013\010Від імені Дарнаса я хочу запропонувати свою допомогу у відродженні цих земель. Допоможеш мені?",
    ["npcs"] = { [1] = 253092 },
    ["priority"] = 3,
    ["roles"] = { ["greeting"] = true, ["reply"] = true, ["box"] = true },
},
    [1143893139] = {
    ["english"] = { [1] = "Yes. I would like to unlearn my class talents." },
    ["text"] = "Так. Я хочу забути свої класові таланти.",
    ["npcs"] = { [1] = 1901 },
    ["priority"] = 3,
    ["roles"] = { ["reply"] = true },
},
    ["274781:tebp"] = {
        ["english"] = { [1] = "The barbershop" },
        ["text"] = "Перукарня",
        ["npcs"] = { [1] = 274781 },
        ["roles"] = { ["reply"] = true },
        ["priority"] = 3,
        ["identities"] = {
            [1] = { ["kind"] = "code", ["value"] = "tebp" },
        },
    },
}
for key, row in pairs(rows) do
    local existing = addonTable.gossip_hashed.rows[key]
    if existing then
        existing.alternatives = existing.alternatives or {}
        existing.alternatives[#existing.alternatives + 1] = row
    else addonTable.gossip_hashed.rows[key] = row end
end
